import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = next(iterator)
            B = next(iterator)
        except StopIteration:
            break

        current_A = list(A)

        impossible = False
        for i in range(N):
            if current_A[i] > B[i]:
                impossible = True
                break

        if impossible:
            print("-1")
            continue

        ops = []
        done = [False] * N

        while True:
            target_chars = set()
            for i in range(N):
                if not done[i]:
                    target_chars.add(B[i])

            if not target_chars:
                break

            min_char = min(target_chars)

            indices = []
            for i in range(N):
                if not done[i] and B[i] == min_char:
                    if current_A[i] != min_char:
                        indices.append(i)
                        current_A[i] = min_char
                    done[i] = True

            if not indices:
                break

            ops.append(indices)

        print(len(ops))
        for op in ops:
            print(f"{len(op)} {' '.join(map(str, sorted(op)))}")

if __name__ == "__main__":
    solve()
